class Solution:
    def countDistinctStrings(self, s: str, k: int) -> int:
        MOD = 1_000_000_007
        return pow(2, len(s) - k + 1, MOD)

class Solution {
public:
    int countDistinctStrings(std::string s, int k) {
        long long mod = 1000000007;
        int exp = s.length() - k + 1;
        long long base = 2;
        long long res = 1;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
};

class Solution {
    public int countDistinctStrings(String s, int k) {
        long mod = 1_000_000_007L;
        int exp = s.length() - k + 1;
        long base = 2;
        long res = 1;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return (int) res;
    }
}

var countDistinctStrings = function(s, k) {
    const mod = 1000000007n;
    let exp = BigInt(s.length - k + 1);
    let base = 2n;
    let res = 1n;
    while (exp > 0n) {
        if (exp % 2n === 1n) res = (res * base) % mod;
        base = (base * base) % mod;
        exp /= 2n;
    }
    return Number(res);
};
